   643→  /**
   644→   * Parses image response from OpenRouter API
   645→   * OpenRouter returns images in an 'images' array within the assistant message
   646→   *
   647→   * @private
   648→   */
   649→  private parseImageResponse(data: any): { base64?: string; url?: string } {
   650→    // OpenRouter returns images as base64 data URLs in the 'images' array
   651→    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }
   652→
   653→    try {
   654→      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));
   655→
   656→      if (data.choices && data.choices[0] && data.choices[0].message) {
   657→        const message = data.choices[0].message;
   658→
   659→        // Primary format: images array (OpenRouter standard)
   660→        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
   661→          const imageData = message.images[0];
   662→          console.log('[ImageGen] Found image in images array, type:', typeof imageData);
   663→
   664→          // Images are returned as data URLs (data:image/png;base64,...)
   665→          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
   666→            return { base64: imageData };
   667→          }
   668→
   669→          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
   670→          if (typeof imageData === 'object') {
   671→            // Check for image_url.url format (OpenRouter Gemini format)
   672→            if (imageData.image_url?.url) {
   673→              console.log('[ImageGen] Found image in image_url.url format');
   674→              const url = imageData.image_url.url;
   675→              if (url.startsWith('data:image')) {
   676→                return { base64: url };
   677→              }
   678→              return { url };
   679→            }
   680→            // Check for b64_json format
   681→            if (imageData.b64_json) {
   682→              return { base64: `data:image/png;base64,${imageData.b64_json}` };
   683→            }
   684→            // Check for direct base64/url
   685→            if (imageData.base64) {
   686→              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
   687→            }
   688→            if (imageData.url) {
   689→              return { url: imageData.url };
   690→            }
   691→          }
   692→        }
   693→
   694→        // Check content for embedded base64 or URLs
   695→        const content = message.content;
   696→        if (typeof content === 'string') {
   697→          // Check if content contains base64 image data
   698→          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
   699→          if (base64Match) {
   700→            console.log('[ImageGen] Found base64 image in content');
   701→            return { base64: base64Match[0] };
   702→          }
   703→
   704→          // Check for URL in content
   705→          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
   706→          if (urlMatch) {
   707→            console.log('[ImageGen] Found URL in content');
   708→            return { url: urlMatch[0] };
   709→          }
   710→        }
   711→
   712→        // Check for structured image data (fallback)
   713→        if (message.image) {
   714→          console.log('[ImageGen] Found image in message.image');
   715→          return {
   716→            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
   717→            url: message.image.url,
   718→          };
   719→        }
   720→      }
   721→
   722→      // Fallback: return empty (will need to handle in caller)
   723→      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
   724→      if (data.choices?.[0]?.message) {
   725→        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
   726→      }
   727→      return {};
   728→    } catch (error) {
   729→      console.error('[ImageGen] Error parsing image response:', error);
   730→      return {};
   731→    }
   732→  }
   733→
   734→  /**
   735→   * Client-side rate limiting check
   736→   * Limits to approximately 10 requests per minute
   737→   *
   738→   * @private
   739→   */
   740→  private checkRateLimit(): boolean {
   741→    const now = Date.now();
   742→    const minuteAgo = now - 60000;
   743→
   744→    // Reset counter if a minute has passed
   745→    if (this.lastRequestTime < minuteAgo) {
   746→      this.requestCount = 0;
   747→    }
   748→
   749→    // Check if under limit
   750→    if (this.requestCount >= 10) {
   751→      return false;
   752→    }
   753→
   754→    // Update counters
   755→    this.requestCount++;
   756→    this.lastRequestTime = now;
   757→
   758→    return true;
   759→  }
   760→
   761→  /**
   762→   * Checks if error is non-retryable (auth, validation, etc.)
   763→   *
   764→   * @private
   765→   */
   766→  private isNonRetryableError(error: any): boolean {
   767→    if (!error) return false;
   768→
   769→    const errorMessage = error.message || error.toString();
   770→
   771→    // Don't retry authentication errors
   772→    if (errorMessage.includes('401') || errorMessage.includes('403')) {
   773→      return true;
   774→    }
   775→
   776→    // Don't retry validation errors
   777→    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
   778→      return true;
   779→    }
   780→
   781→    // Don't retry rate limit errors (need to wait)
   782→    if (errorMessage.includes('429') || errorMessage.includes('RATE_LIMIT')) {
   783→      return true;
   784→    }
   785→
   786→    return false;
   787→  }
   788→
   789→  /**
   790→   * Sleep utility for retry delays
   791→   *
   792→   * @private
   793→   */
   794→  private sleep(ms: number): Promise<void> {
   795→    return new Promise((resolve) => setTimeout(resolve, ms));
   796→  }
   797→}
   798→
   799→/**
   800→ * Creates a new OpenRouter image client with API key from environment
   801→ *
   802→ * @returns OpenRouterImageClient instance or null if API key not available
   803→ *
   804→ * @example
   805→ * const client = createImageClient();
   806→ * if (client) {
   807→ *   const response = await client.generateOutfitImage(description);
   808→ * }
   809→ */
   810→export function createImageClient(): OpenRouterImageClient | null {
   811→  const apiKey = process.env.OPENROUTER_API_KEY;
   812→
   813→  if (!apiKey) {
   814→    console.warn('[ImageGen] OPENROUTER_API_KEY not found in environment');
   815→    return null;
   816→  }
   817→
   818→  try {
